UPDATE public.sondas_config SET question_text_en = $rsv$When sudden provocations, arguments, or outer chaos hit, how does your reaction curve accelerate?$rsv$, options_json_en = to_jsonb(json_build_array(json_build_object('label',$rsv$Destructive Roller Coaster. I lose control in seconds. I react with rage, shouting, or explosive tears, burning through my entire cellular battery and wrecking my relationships.$rsv$,'value',0), json_build_object('label',$rsv$Toxic Suppression. I swallow the emotion to "avoid making a scene," but the resentment burns me from the inside, breeding acidity and biological heaviness.$rsv$,'value',25), json_build_object('label',$rsv$Standard Oscillation. I try to stay calm, but eventually I take the bait if the provocation keeps coming. It takes me hours to return to my baseline frequency.$rsv$,'value',50), json_build_object('label',$rsv$Regulated Flow. I feel the heat wave rise, but there is a space of silence between the trigger and my action. I choose my response consciously before I act.$rsv$,'value',75), json_build_object('label',$rsv$Active Neutrality. Zero drama. Provocations disintegrate the moment they touch my field. I observe the disturbance without my heart rate rising. I am the eye of the hurricane.$rsv$,'value',100))::text) WHERE id = '11d7ea8c-6e82-4be3-a14c-d1e973cf679b';
