UPDATE public.sondas_config SET question_text_en = $rsv$How much authority does the outer world (opinions, criticism, rejection, or likes) hold over your inner peace?$rsv$, options_json_en = to_jsonb(json_build_array(json_build_object('label',$rsv$Puppet of the Environment. My worth rises and falls with how people treat me. A negative comment or a rejection destroys my whole day and drains my life energy completely.$rsv$,'value',0), json_build_object('label',$rsv$Defensive Vulnerability. I chase approval and take offense easily. I spend huge amounts of energy justifying myself or trying to change the image others hold of me.$rsv$,'value',25), json_build_object('label',$rsv$Conditioned Balance. I stay stable as long as my environment approves of me, but the projections or criticism of my inner circle still slip in and shake my center.$rsv$,'value',50), json_build_object('label',$rsv$Active Self-Reference. I listen to useful feedback, but my peace is non-negotiable. I do not merge with the applause, and I do not sink with the criticism.$rsv$,'value',75), json_build_object('label',$rsv$Holographic Shield. Outside opinion is only telemetry, not truth. My field is impenetrable. I need no validation because my code is already approved by the Source.$rsv$,'value',100))::text) WHERE id = '8ef64e98-9102-4fbe-856d-c526df9842c3';
