UPDATE public.sondas_config SET question_text_en = $rsv$When you go through a deep wound or a loss (relational or material), how does your system process the impact?$rsv$, options_json_en = to_jsonb(json_build_array(json_build_object('label',$rsv$Total Identification. "I am my wound." I sink into victimhood, use the pain as an excuse to freeze, and demand that others validate my suffering.$rsv$,'value',0), json_build_object('label',$rsv$Forced Anesthesia. I flee the pain. I suppress it with distractions, overwork, substances, or rebound relationships so I never feel the impact of the darkness.$rsv$,'value',25), json_build_object('label',$rsv$Therapeutic Rumination. I talk about the pain constantly. I understand logically why it hurts, but I stay trapped in the cyclical analysis without ever letting it go.$rsv$,'value',50), json_build_object('label',$rsv$Code Extraction. I let myself feel the impact without resistance, extract the lesson (the data), and release the emotional density quickly so I can keep moving forward.$rsv$,'value',75), json_build_object('label',$rsv$Unbreakable Fuel. Pain is instant alchemy. Friction enters my system and automatically turns into a fierce expansion of consciousness.$rsv$,'value',100))::text) WHERE id = 'cba41649-f098-4aa7-9f12-004dd53188ae';
