UPDATE public.sondas_config SET question_text_en = $rsv$When you interact with people running in high density (complaint, fear, stagnation), how do you hold your boundaries?$rsv$, options_json_en = to_jsonb(json_build_array(json_build_object('label',$rsv$Karmic Sponge. I absorb everyone's density. I suffer the "Savior Syndrome," emptying my own ship to try to fill someone else's, and I collapse right along with them.$rsv$,'value',0), json_build_object('label',$rsv$Active Drain. I pour my life energy into giving unsolicited advice or trying to "fix" others. I end up exhausted and nothing changes.$rsv$,'value',25), json_build_object('label',$rsv$Blurry Boundary. I support without over-involving myself, but I often carry other people's mental heaviness home to my mind and my rest.$rsv$,'value',50), json_build_object('label',$rsv$Clean Containment. I offer presence from my center. I know how to set a firm boundary when the interaction becomes a drain on my prana, and I step back without guilt.$rsv$,'value',75), json_build_object('label',$rsv$Surgical Compassion. My presence alone lifts the room, but I never lower my frequency to "save" anyone. I hold the light. Zero energy bleed.$rsv$,'value',100))::text) WHERE id = 'f69f4c1f-2b97-461d-94b1-fef47e52f283';
