UPDATE public.sondas_config SET question_text_en = $rsv$How does your Emotional Engine handle your own mistakes, failures, or earlier versions of yourself?$rsv$, options_json_en = to_jsonb(json_build_array(json_build_object('label',$rsv$Perpetual Punishment. I beat myself up inside every single day over my mistakes. I feel I am "damaged" and that my past failures define my worth right now.$rsv$,'value',0), json_build_object('label',$rsv$Cyclical Regret. I struggle to forgive myself. My mind keeps traveling back to moments where I fell short, breeding shame and heaviness.$rsv$,'value',25), json_build_object('label',$rsv$Intellectual Forgiveness. Logically I know it is over and I understand the mistake, but I still feel a dense weight in my chest whenever someone or something reminds me of it.$rsv$,'value',50), json_build_object('label',$rsv$Software Update. I see the mistake, extract the lesson, correct the code of my behavior, and move on without carrying the emotional backpack.$rsv$,'value',75), json_build_object('label',$rsv$Quantum Amnesia. The past does not exist, it is only dissolved geometry. There is no guilt, only integrated data. I honor my earlier avatars and release them instantly.$rsv$,'value',100))::text) WHERE id = 'ac91c699-1ad7-466a-9dc1-bb6b69c3c4b7';
