UPDATE public.sondas_config SET question_text_en = $rsv$When a cycle closes organically (a relationship, a project, an object, an identity), how quickly do you allow it to disintegrate?$rsv$, options_json_en = to_jsonb(json_build_array(json_build_object('label',$rsv$Forced Retention. I fight against gravity. I cling to dead people or situations through manipulation, pleading, or control, losing all my dignity and energy.$rsv$,'value',0), json_build_object('label',$rsv$Painful Resistance. I let go, but I tear myself apart in the process. I resist the change, constantly longing for "what was" and refusing to see the new path.$rsv$,'value',25), json_build_object('label',$rsv$Operational Melancholy. I release the form, but I hold a long mental attachment. It takes me months to empty the space so something new can enter.$rsv$,'value',50), json_build_object('label',$rsv$Architectural Closure. I give thanks for the role that person or situation played in my life and open the door for it to leave with respect, clearing my field fast.$rsv$,'value',75), json_build_object('label',$rsv$Zero Friction. Entropy honored. I understand that matter is transient. What enters my life is honored; what leaves is released without my heart rate stirring.$rsv$,'value',100))::text) WHERE id = 'c6a792ef-7913-4990-9984-ec8f0ec35403';
