UPDATE public.sondas_config SET question_text_en = $rsv$The moment you make a big payment or investment, what sensation takes over your nervous system?$rsv$, options_json_en = to_jsonb(json_build_array(json_build_object('label',$rsv$Panic and contraction. I feel like the money is running out, like I'm losing something vital.$rsv$,'value',0), json_build_object('label',$rsv$Fear and guilt. I pay because I have to, but the letting go hurts and I tally up what I lost.$rsv$,'value',25), json_build_object('label',$rsv$Mechanical transaction. I see it as a normal exchange. It neither excites me nor terrifies me.$rsv$,'value',50), json_build_object('label',$rsv$Conscious flow. I'm grateful to have the energy to pay. It keeps my ecosystem in motion.$rsv$,'value',75), json_build_object('label',$rsv$Total expansion. Every outflow is blessed. I know the field returns a greater wave.$rsv$,'value',100))::text) WHERE id = '30523b67-c675-4e3d-b67b-3f01d974f7cb';
