UPDATE public.sondas_config SET question_text_en = $rsv$How do you perceive your capacity to generate income and draw resources into your timeline?$rsv$, options_json_en = to_jsonb(json_build_array(json_build_object('label',$rsv$Survival struggle. I feel money flees from me. Getting out of the stress feels impossible.$rsv$,'value',0), json_build_object('label',$rsv$Extreme effort. I sacrifice all my life force to earn barely enough.$rsv$,'value',25), json_build_object('label',$rsv$Conditional stability. I generate what I need by working hard, but if I stop, the flow collapses.$rsv$,'value',50), json_build_object('label',$rsv$Magnetic attraction. My skills generate steady income without draining me.$rsv$,'value',75), json_build_object('label',$rsv$Instant materialization. I don't chase money; I am the gravity that pulls it in.$rsv$,'value',100))::text) WHERE id = 'b1c85bdc-fbfb-42ad-9d45-3af52381eec9';
