UPDATE public.sondas_config SET question_text_en = $rsv$When you think about your financial situation against what you want to materialize, what is your baseline state?$rsv$, options_json_en = to_jsonb(json_build_array(json_build_object('label',$rsv$Resentment. I hate my situation, I envy those who have more. The system is unfair.$rsv$,'value',0), json_build_object('label',$rsv$Chronic worry. I always feel something is missing. It's never enough.$rsv$,'value',25), json_build_object('label',$rsv$Passive acceptance. I'm content. I'd like to be better off, but I won't risk my comfort.$rsv$,'value',50), json_build_object('label',$rsv$Active gratitude. I'm grateful for what I've materialized and I operate with confidence to expand my impact.$rsv$,'value',75), json_build_object('label',$rsv$Dimensional sovereignty. Money doesn't dictate my peace. My consciousness shapes matter at will.$rsv$,'value',100))::text) WHERE id = 'a602bfd2-0757-4dec-95bb-4131b37ca118';
