UPDATE public.sondas_config SET question_text_en = $rsv$When it comes to charging for your energy, your time, or the value of your creations, what is your emission frequency?$rsv$, options_json_en = to_jsonb(json_build_array(json_build_object('label',$rsv$Leak from scarcity. I give my work away, charge next to nothing, or feel terrified to charge because I feel I'm not worth it or that people will reject me.$rsv$,'value',0), json_build_object('label',$rsv$Resentful exchange. I charge less than I need. I feel people are "doing me a favor" by paying me, and I build up resentment toward the system for not valuing me.$rsv$,'value',25), json_build_object('label',$rsv$Mechanical transaction. I charge the market standard. There's no extreme friction, but I don't feel I'm expanding my limit of value either.$rsv$,'value',50), json_build_object('label',$rsv$Price sovereignty. I know the value of my code. I charge what is fair for my expansion and I don't negotiate my rates out of fear.$rsv$,'value',75), json_build_object('label',$rsv$Authority magnetism. I set the frequency. I charge from absolute certainty. The market doesn't question me; the market aligns to the gravity of my value.$rsv$,'value',100))::text) WHERE id = 'f2eed813-a810-432d-a1b3-7934962aa841';
