UPDATE public.sondas_config SET question_text_en = $rsv$How do you manage financial energy once it has entered your container (your accounts)?$rsv$, options_json_en = to_jsonb(json_build_array(json_build_object('label',$rsv$Financial hemorrhage. I spend impulsively on instant gratification or things I don't need to fill emotional voids. Money burns a hole in my pocket.$rsv$,'value',0), json_build_object('label',$rsv$Contraction from terror. I save out of absolute panic of going broke. I hold the money tight, stalling its flow and living in mental scarcity even when I have funds.$rsv$,'value',25), json_build_object('label',$rsv$Passive management. I cover my needs and keep a margin. There are no destructive leaks, but my money sits inert, it isn't multiplying.$rsv$,'value',50), json_build_object('label',$rsv$Tactical allocation. I hold energy with purpose. I invest in assets, tools, or experiences that expand my biology and my capacity to generate more flow.$rsv$,'value',75), json_build_object('label',$rsv$Quantum multiplier. I'm a clean channel. Energy comes in, I redirect part toward my evolution and part toward high-frequency ecosystems (like Red Solar Viva). Every outflow is a mathematical investment that returns multiplied.$rsv$,'value',100))::text) WHERE id = 'e7ee8f2e-0bb1-43a3-90b3-e75f208d552d';
