UPDATE public.sondas_config SET question_text_en = $rsv$How does your body (your Avatar) feel after eating and throughout the rest of the day?$rsv$, options_json_en = to_jsonb(json_build_array(json_build_object('label',$rsv$Heavy, with mental fog. Fatigue hits me almost right away; my digestion steals my energy instead of giving it to me.$rsv$,'value',0), json_build_object('label',$rsv$I feel frequent bloating or heaviness. I tend to lean on stimulants (sugar/coffee) to keep from crashing in the mid-afternoon.$rsv$,'value',25), json_build_object('label',$rsv$Functional. My energy is stable most of the time, though sometimes I eat out of inertia or anxiety, not out of need.$rsv$,'value',50), json_build_object('label',$rsv$Light most of the time. I respect my eating windows, I choose foods that nourish me, and I rarely feel energy dips.$rsv$,'value',75), json_build_object('label',$rsv$Clean, sustained energy. My body feels electric, empty of density, and running like a superconductor.$rsv$,'value',100))::text) WHERE id = '57e218db-41ac-4a57-b340-da60e44e8257';
