UPDATE public.sondas_config SET question_text_en = $rsv$When you wake up in the morning, what energy level does your system boot up with?$rsv$, options_json_en = to_jsonb(json_build_array(json_build_object('label',$rsv$Total resistance. It takes everything I have to get out of bed; I wake up exhausted, foggy, and with no drive to start the day.$rsv$,'value',0), json_build_object('label',$rsv$I wake up sluggish. I need multiple alarms, time to register that I'm awake, and something external to get going.$rsv$,'value',25), json_build_object('label',$rsv$A standard wake-up. I get up because I have things to do; the energy is enough, but it isn't expansive.$rsv$,'value',50), json_build_object('label',$rsv$I wake up easily and with near-immediate clarity. My mind switches on fast and my body is ready.$rsv$,'value',75), json_build_object('label',$rsv$Electric ignition. I open my eyes with absolute sharpness, ready to materialize the day's vision.$rsv$,'value',100))::text) WHERE id = 'd7cec60a-98a3-40ee-b9bb-3a14d33781c1';
