UPDATE public.sondas_config SET question_text_en = $rsv$How do you manage the energy stored in your physical structure (exercise, mobility, tension)?$rsv$, options_json_en = to_jsonb(json_build_array(json_build_object('label',$rsv$Almost total sedentary life. My body feels stiff, stagnant, or in constant pain from inactivity.$rsv$,'value',0), json_build_object('label',$rsv$Very occasional or light movement. I spend most of my day in physical inertia.$rsv$,'value',25), json_build_object('label',$rsv$I keep an average exercise routine. I get my movement in, but sometimes it feels like an obligation.$rsv$,'value',50), json_build_object('label',$rsv$I train consistently. My body has strength and flexibility, and I use movement to release stress.$rsv$,'value',75), json_build_object('label',$rsv$High voltage. My training transfers energy without blocks. My structure is an open, strong channel.$rsv$,'value',100))::text) WHERE id = '36e65d80-b293-4a38-b0cf-fa359e9c27d5';
