UPDATE public.sondas_config SET question_text_en = $rsv$What is your level of direct sunlight exposure, and how does it affect your biological rhythm?$rsv$, options_json_en = to_jsonb(json_build_array(json_build_object('label',$rsv$Almost total isolation. I spend the day under artificial light (LED/fluorescent). My skin rarely touches the sun; I feel disconnected from the natural cycle.$rsv$,'value',0), json_build_object('label',$rsv$Accidental exposure. I only catch sun walking to the car or the office. My system has no conscious photonic charge.$rsv$,'value',25), json_build_object('label',$rsv$Moderate exposure. I try to step outside for a bit each day, but I don't have an established solar anchoring protocol.$rsv$,'value',50), json_build_object('label',$rsv$Active protocol. I seek out the sun intentionally at sunrise or during the day. I feel how the light regulates my energy and my rest.$rsv$,'value',75), json_build_object('label',$rsv$Light-fed. My body is a solar panel. The morning anchoring is non-negotiable, and my system runs in perfect sync with the frequency of the Sun.$rsv$,'value',100))::text) WHERE id = 'd5043ccd-46a0-425b-83d0-e4ea21aa0d1f';
