UPDATE public.sondas_config SET question_text_en = $rsv$During the day, what is the quality of your breathing and the state of your nervous system?$rsv$, options_json_en = to_jsonb(json_build_array(json_build_object('label',$rsv$Shallow, rapid breathing. I live in a constant state of "alert," with a tight chest and involuntary muscle tension.$rsv$,'value',0), json_build_object('label',$rsv$Latent tension. My breathing is mechanical; I notice that I hold my breath or sigh often from accumulated stress.$rsv$,'value',25), json_build_object('label',$rsv$Basic stability. I breathe normally most of the time, though I lose my rhythm under moderate pressure.$rsv$,'value',50), json_build_object('label',$rsv$Conscious control. I use my breath to calm my system. I'm aware of my states of tension and can bring them down at will.$rsv$,'value',75), json_build_object('label',$rsv$Total coherence. My breathing is deep, nasal, and rhythmic. My nervous system is a still lake that doesn't react, but responds with precision.$rsv$,'value',100))::text) WHERE id = '8082a55e-5748-4277-8a53-b73074e651a8';
