UPDATE public.sondas_config SET question_text_en = $rsv$What is the level of purity and isolation in your rest environment (Void Phase / Night)?$rsv$, options_json_en = to_jsonb(json_build_array(json_build_object('label',$rsv$I sleep with my phone in bed or in my hand. Notifications ring or vibrate. The room has LED lights or screens on, and the home Wi-Fi is active near me. My sleep is an extension of the daytime noise.$rsv$,'value',0), json_build_object('label',$rsv$My phone is on the nightstand, face down but connected to the network. The room has residual artificial light, and I have no conscious filter over what I breathe or hear while I sleep.$rsv$,'value',25), json_build_object('label',$rsv$I put my phone on silent or away from the bed. I try to keep the room dark, but I still sleep inside the active field of the home Wi-Fi.$rsv$,'value',50), json_build_object('label',$rsv$My nighttime protocol is strict. The phone goes on Airplane Mode or stays in another room. I turn off the home Wi-Fi router when I sleep. The darkness and silence in my rest chamber are near total.$rsv$,'value',75), json_build_object('label',$rsv$My rest environment is a biological sanctuary. Zero active networks (router off, phone out). Zero lights (absolute darkness). Purified ventilation. When I close my eyes, the physical Dome blocks the entire external matrix; the Avatar regenerates in Zero Friction.$rsv$,'value',100))::text) WHERE id = 'f649c5d9-18a3-4704-9a12-e40fd4de45fb';
-- FISICO · sonda 8
UPDATE public.sondas_config SET question_text_en = $rsv$What is the synthetic chemical load that your Avatar's Membrane (skin, mucosa, airways) absorbs in your daily life?$rsv$, options_json_en = to_jsonb(json_build_array(json_build_object('label',$rsv$Total exposure to endocrine disruptors. I use fluoride toothpaste, deodorants with heavy metals (aluminum), and chemical fragrances without question. My system burns huge amounts of energy trying to clear this daily toxicity.$rsv$,'value',0), json_build_object('label',$rsv$I'm aware that chemicals affect my biology, but I prioritize the convenience of the three-dimensional matrix. I keep buying commercial hygiene and household cleaning products, passively taking on their toxic load.$rsv$,'value',25), json_build_object('label',$rsv$I've replaced the most obvious offenders (e.g., fluoride-free toothpaste, natural deodorant), but I'm still exposed to sulfates, parabens, or microplastics in soaps, detergents, and the air of my indoor space.$rsv$,'value',50), json_build_object('label',$rsv$I actively review the architecture of the ingredients. My personal care is biocompatible for the most part. I've purged heavy metals, hormone disruptors, and synthetic fragrances from my ecosystem.$rsv$,'value',75), json_build_object('label',$rsv$My Membrane is sealed against industrial entropy. Everything that touches my skin or enters my mouth is 100% natural, organic, or made by me. The Avatar wastes no prana clearing toxins; the energy is retained for absolute conductivity.$rsv$,'value',100))::text) WHERE id = '391c9653-fe4a-4205-9c7f-1450d580ddc3';
