UPDATE public.sondas_config SET question_text_en = $rsv$When a problem shows up or you have to make a decision, how does your resolution algorithm operate?$rsv$, options_json_en = to_jsonb(json_build_array(json_build_object('label',$rsv$Freeze and Avoid. I get overwhelmed instantly. I put the decision off as long as possible or desperately hope someone else (the matrix) will choose for me.$rsv$,'value',0), json_build_object('label',$rsv$Prolonged Doubt. I question my options over and over, constantly seek outside validation, and distrust my own calculations. The decision drains my prana.$rsv$,'value',25), json_build_object('label',$rsv$Standard Resolution. I weigh pros and cons. I make the decision, though sometimes a residue of doubt remains.$rsv$,'value',50), json_build_object('label',$rsv$Fast Clarity. I analyze the geometry of the problem without attachment. I cut the unnecessary variables and make firm, fast decisions, owning the outcome.$rsv$,'value',75), json_build_object('label',$rsv$Intuitive Execution. The resolution emerges from the void. I know exactly what to do instantly. I make high-impact decisions without a second of friction or static afterward.$rsv$,'value',100))::text) WHERE id = '96b1125b-0edc-4227-96dd-b5e6aee59dfc';
