UPDATE public.sondas_config SET question_text_en = $rsv$When material reality suddenly disrupts your plans or throws an "error" into your design, how long does your mind take to recalculate the route?$rsv$, options_json_en = to_jsonb(json_build_array(json_build_object('label',$rsv$System Collapse. I fight against reality. My mind locks onto the complaint ("why is this happening to me?"). I can lose entire days denying the new scenario.$rsv$,'value',0), json_build_object('label',$rsv$Sustained Friction. I eventually accept the problem, but I burn enormous amounts of mental RAM frustrated over what the original plan "should have been".$rsv$,'value',25), json_build_object('label',$rsv$Mechanical Resilience. I accept the change in variables and look for solutions, but the process takes conscious effort and leaves me with cognitive fatigue.$rsv$,'value',50), json_build_object('label',$rsv$Agile Recalculation. I see the obstacle as a simple change in telemetry. I redirect my vector quickly and design the solution without wasting bandwidth on complaints.$rsv$,'value',75), json_build_object('label',$rsv$Liquid Architecture. Zero friction. I instantly understand the purpose of the obstacle. I use the problem's own momentum to accelerate toward a higher route.$rsv$,'value',100))::text) WHERE id = 'd40bcb7c-1d1f-463f-a689-f4a13186f0d9';
-- MENTAL · sonda 5
UPDATE public.sondas_config SET question_text_en = $rsv$How clearly can you tell the voice of your conditioning (fear/ego) apart from the signal of your Original Code (intuition)?$rsv$, options_json_en = to_jsonb(json_build_array(json_build_object('label',$rsv$Deep Deafness. The ego is the only voice in my operating system. All my decisions are logically based on avoiding pain, seeking safety, or keeping control.$rsv$,'value',0), json_build_object('label',$rsv$Constant Confusion. I sense the intuition in the background, but the mental noise and the "rules" of the outside world crush it. I freeze trying to figure out which voice to listen to.$rsv$,'value',25), json_build_object('label',$rsv$Intermittent Listening. I recognize my original code, but I often negotiate with the ego to choose the "safer" path in the eyes of society.$rsv$,'value',50), json_build_object('label',$rsv$Primary Tuning. My intuition's signal is clear and dominant. I trust my inner radar and act, even if third-dimensional logic tells me otherwise.$rsv$,'value',75), json_build_object('label',$rsv$Direct Channeling. The ego is just a telemetry panel, never the pilot. I execute the orders of my quantum field with telepathic certainty. There's no doubt or negotiation.$rsv$,'value',100))::text) WHERE id = '77aabb01-b95f-4f93-a3e0-5483779ffc1b';
