UPDATE public.sondas_config SET question_text_en = $rsv$What is the quality of the information (external code) you let into your processor every day?$rsv$, options_json_en = to_jsonb(json_build_array(json_build_object('label',$rsv$Junk Consumption. My mind absorbs pure entropy: third-dimensional fear news, gossip, other people's drama, and hyper-stimulating content without any filter.$rsv$,'value',0), json_build_object('label',$rsv$Passive Exposure. I don't actively seek drama, but I let the social algorithm or my environment dictate what my mind feeds on. I swallow a lot of useless information out of boredom.$rsv$,'value',25), json_build_object('label',$rsv$Basic Filtering. I try to consume useful information (books, podcasts), but I still fall often into digital distraction rabbit holes that clutter my RAM.$rsv$,'value',50), json_build_object('label',$rsv$Conscious Curation. I'm the guardian of my mental membrane. I strictly consume information that expands my architecture, teaches skills, or raises my frequency.$rsv$,'value',75), json_build_object('label',$rsv$Architectural Isolation. Zero static. My diet is high-conductivity knowledge and pure emptiness. I dictate what enters my mind with absolute rigor.$rsv$,'value',100))::text) WHERE id = '999d9a1b-5483-4ee5-88d0-930f764802fb';
