UPDATE public.sondas_config SET question_text_en = $rsv$What is the tone and frequency of the voice you speak to yourself with inside your own head?$rsv$, options_json_en = to_jsonb(json_build_array(json_build_object('label',$rsv$Destructive Tyrant. My inner voice is my worst enemy. I insult myself, belittle myself, and constantly remind myself of my failures. Self-hatred is the background noise of my life.$rsv$,'value',0), json_build_object('label',$rsv$Critical Judge. I'm excessively hard on myself. I demand perfection, and when I fail, my mind punishes me with severe, draining monologues.$rsv$,'value',25), json_build_object('label',$rsv$Wavering Tolerance. I try to be kind to myself, but under high stress the critical voice comes back and I doubt my own operational worth.$rsv$,'value',50), json_build_object('label',$rsv$Conscious Coach. My dialogue is constructive and firm. If I make a mistake, my mind analyzes the failure mechanically without insulting the Avatar.$rsv$,'value',75), json_build_object('label',$rsv$Silence of Sovereignty. There aren't "two people" talking in my head. The inner dialogue ceases. I operate in absolute communion with myself; the mind is an unshakable ally of light and architecture.$rsv$,'value',100))::text) WHERE id = 'fc6c1ed3-5c87-4133-a6e4-1be895bc20d5';
