UPDATE public.sondas_config SET question_text_en = $rsv$Which part of your social circle reflects your past instead of your future?$rsv$, options_json_en = to_jsonb(json_build_array(json_build_object('label',$rsv$Prisoner of my origins. My whole circle lives in lack and complaint. I stay out of fear of loneliness, even though I know it drags me down.$rsv$,'value',0), json_build_object('label',$rsv$Toxic loyalty. I hold on to old friendships that no longer fit me. I go to gatherings out of obligation and come back exhausted, pretending to be someone I no longer am.$rsv$,'value',25), json_build_object('label',$rsv$Passive transition. I'm slowly drifting away from low-frequency people, but I haven't found a new tribe yet. I'm in a functional isolation.$rsv$,'value',50), json_build_object('label',$rsv$Conscious pruning. I cut ties with conformity. My circle is small but select: people who demand that I rise to a higher level.$rsv$,'value',75), json_build_object('label',$rsv$Ecosystem of creators. My network is a force field. I surround myself only with awakened people who speak the language of creating without fear.$rsv$,'value',100))::text) WHERE id = '221ba734-d63a-4014-86e5-b519e5302037';
