UPDATE public.sondas_config SET question_text_en = $rsv$How much of your life force do you hand over to family out of guilt, obligation, or emotional blackmail?$rsv$, options_json_en = to_jsonb(json_build_array(json_build_object('label',$rsv$Total servitude. My family demands my time, energy, or money, and I give it all up out of fear of being "the bad one." I end up empty.$rsv$,'value',0), json_build_object('label',$rsv$Fragile boundary. I try to say "no," but emotional blackmail bends me. I give in, do favors I hate, and pile up resentment.$rsv$,'value',25), json_build_object('label',$rsv$Diplomatic negotiation. I set basic boundaries, but I struggle to hold them under pressure. What the family will say still weighs on me.$rsv$,'value',50), json_build_object('label',$rsv$Firm boundaries. I have clear limits. I support my people when it truly comes from the heart, but I don't carry guilt or false debts.$rsv$,'value',75), json_build_object('label',$rsv$Zero guilt. I don't negotiate with manipulation. I give from abundance and pull my energy back instantly in the face of blackmail, without remorse.$rsv$,'value',100))::text) WHERE id = '287e0648-4ac1-44a2-92f0-9113dcb0878c';
-- ORBITA · sonda 4
UPDATE public.sondas_config SET question_text_en = $rsv$In everyday, mainstream settings, how much do you change who you really are to fit in?$rsv$, options_json_en = to_jsonb(json_build_array(json_build_object('label',$rsv$Total camouflage. I wear a mask 24 hours a day. I pretend to agree with everything just to be accepted.$rsv$,'value',0), json_build_object('label',$rsv$Silence out of fear. I don't pretend, but I hide my gifts and my vision out of fear of ridicule or other people's judgment.$rsv$,'value',25), json_build_object('label',$rsv$Half expression. I'm authentic only with my most trusted circle. With everyone else, I keep a low profile.$rsv$,'value',50), json_build_object('label',$rsv$I show up openly. I am who I am. If the way I am makes someone uncomfortable, I don't apologize or shrink.$rsv$,'value',75), json_build_object('label',$rsv$Total authenticity. I'm 100% myself anywhere. My energy is so steady that the environment adjusts to me, or it carries me to better places.$rsv$,'value',100))::text) WHERE id = 'dcfd6582-75ff-4108-b64d-cee974edd54c';
-- ORBITA · sonda 5
UPDATE public.sondas_config SET question_text_en = $rsv$When someone who drains you enters your field (victimhood, gossip, complaint), how does your system react?$rsv$, options_json_en = to_jsonb(json_build_array(json_build_object('label',$rsv$Immediate contagion. Their negativity drags me in. I join the gossip and lower my energy to keep them company in their darkness.$rsv$,'value',0), json_build_object('label',$rsv$Passive discomfort. It bothers me, but I keep listening out of "politeness." I let them dump their load onto me.$rsv$,'value',25), json_build_object('label',$rsv$Reactive blocking. I cut the conversation off abruptly or get defensive. I stop the leak, but I'm left tense.$rsv$,'value',50), json_build_object('label',$rsv$Elegant deflection. I shift the tone of the conversation or step away without friction. I don't let that noise get into me.$rsv$,'value',75), json_build_object('label',$rsv$Natural repellence. My field holds so much light that whoever drains can't even sustain their presence. They walk away on their own, without me saying a word.$rsv$,'value',100))::text) WHERE id = 'b9667a90-905d-45b1-900e-686d38f5c748';
-- ORBITA · sonda 6
UPDATE public.sondas_config SET question_text_en = $rsv$When a relationship has run its course and is holding back your growth, how quickly do you cut the tie?$rsv$, options_json_en = to_jsonb(json_build_array(json_build_object('label',$rsv$Paralysis from attachment. I spend years knowing I should leave, unable to let go of the comfort of my own cage.$rsv$,'value',0), json_build_object('label',$rsv$Prolonged grief. I end it and go back again and again. I drag out the agony. The break is messy and dramatic.$rsv$,'value',25), json_build_object('label',$rsv$Functional break. I close the cycle, but I carry nostalgia or check in now and then on what the other person is doing.$rsv$,'value',50), json_build_object('label',$rsv$Clean break. I'm grateful for the lesson, close the door, and look ahead, processing the void with maturity.$rsv$,'value',75), json_build_object('label',$rsv$Closure and rebirth. I let go at the root, without drama. The energy I recover turns immediately into a new leap.$rsv$,'value',100))::text) WHERE id = 'fa852b46-d589-4cec-a59d-414cf1d79f96';
