UPDATE public.sondas_config SET question_text_en = $rsv$How much effort do you put into "finding" the new people who truly resonate with you?$rsv$, options_json_en = to_jsonb(json_build_array(json_build_object('label',$rsv$Desperate search. I chase affection and validation. I beg for a place in groups I don't belong to.$rsv$,'value',0), json_build_object('label',$rsv$Forced effort. I seek out alliances or friendships on purpose, but the process feels mechanical.$rsv$,'value',25), json_build_object('label',$rsv$Lukewarm attraction. I trust they'll arrive, but I don't send out a clear signal. New connections are random.$rsv$,'value',50), json_build_object('label',$rsv$Attunement through affinity. By focusing on what I love, I naturally cross paths with people on the same path. The network weaves itself.$rsv$,'value',75), json_build_object('label',$rsv$Force of gravity. I don't search; I attract. I stay in my center, expanding my light, and kindred people arrive in my orbit on their own.$rsv$,'value',100))::text) WHERE id = '3ae5fab6-6e6b-4f63-a53a-1645ff4a7403';
-- ORBITA · sonda 8
UPDATE public.sondas_config SET question_text_en = $rsv$How do you act when you're the one who needs support, holding, or energy from others?$rsv$, options_json_en = to_jsonb(json_build_array(json_build_object('label',$rsv$Wounded wolf. I isolate myself completely. I feel no one understands me and I reject all help out of pride or distrust.$rsv$,'value',0), json_build_object('label',$rsv$Chronic giver. I'm everyone's pillar, but I let no one in. Giving gives me control; receiving makes me feel weak or indebted.$rsv$,'value',25), json_build_object('label',$rsv$Emergency help. I ask for support only in extreme cases, and I treat it like a transaction: I pay for the service and shut the door right away.$rsv$,'value',50), json_build_object('label',$rsv$Conscious openness. I let my tribe hold me. I lower my guard with the right people without feeling I'm losing my freedom.$rsv$,'value',75), json_build_object('label',$rsv$A network that breathes. I understand that hyper-independence also wears me down. I give and receive with equal ease. I let my community nourish me, because we're part of the same whole.$rsv$,'value',100))::text) WHERE id = 'f20a374a-9098-4767-a467-20f4b1edf79f';
