UPDATE public.sondas_config SET question_text_en = $rsv$Which timeline (project, vision, or structure) are you handing your vital, productive energy to every day?$rsv$, options_json_en = to_jsonb(json_build_array(json_build_object('label',$rsv$Total Enslavement. I build someone else's dream inside a system that drains me. I hate what I do and inertia is consuming me.$rsv$,'value',0), json_build_object('label',$rsv$Mechanical Resistance. I do my work only to survive. It doesn't move me at all, but it gives me enough security not to collapse.$rsv$,'value',25), json_build_object('label',$rsv$Operational Transaction. I have a stable job or business. It doesn't fascinate me or lift me, but it's a functional means to live.$rsv$,'value',50), json_build_object('label',$rsv$Project in Transition. I work on my own vision or in an ecosystem that resonates with my values. I feel constant expansion and growth.$rsv$,'value',75), json_build_object('label',$rsv$Architect of the Fractal. My entire productive bandwidth materializes my highest purpose and my Original Code.$rsv$,'value',100))::text) WHERE id = 'e624db76-205f-4df3-adb7-7beb7b4c5e38';
-- VECTOR · sonda 2
UPDATE public.sondas_config SET question_text_en = $rsv$During your blocks of action or main work, how does your system's thermodynamics (your inner fire) feel?$rsv$, options_json_en = to_jsonb(json_build_array(json_build_object('label',$rsv$Fully Shut Off. I feel a heavy emptiness, chronic boredom, or a desperation for the day to end so I can "finally live."$rsv$,'value',0), json_build_object('label',$rsv$Friction from Duty. I feel heaviness. I do things out of forced discipline, but my inner fire is running at a minimum.$rsv$,'value',25), json_build_object('label',$rsv$Functional without a Spark. I'm focused and I solve problems efficiently, but I operate more from intellect than from passion.$rsv$,'value',50), json_build_object('label',$rsv$Clean Combustion. I deeply enjoy what I do. I enter a state of flow and I'm thrilled to watch matter take shape.$rsv$,'value',75), json_build_object('label',$rsv$Productive Ecstasy. Time collapses. Action arises from the void. I recharge with electromagnetic voltage while I execute the work.$rsv$,'value',100))::text) WHERE id = '8d705777-a9a6-4613-990b-88413523e18f';
-- VECTOR · sonda 3
UPDATE public.sondas_config SET question_text_en = $rsv$What percentage of your innate talents and genetic design are you using in your current work?$rsv$, options_json_en = to_jsonb(json_build_array(json_build_object('label',$rsv$Absolute Repression. My true gifts are hidden or atrophied because my environment demands that I operate like a repetitive machine.$rsv$,'value',0), json_build_object('label',$rsv$Conditioned Use. I use my talents only marginally, or as an occasional escape when I have energy to spare on the weekend.$rsv$,'value',25), json_build_object('label',$rsv$Partial Use. I apply some of my natural abilities, but I feel my true potential is held in a waiting room.$rsv$,'value',50), json_build_object('label',$rsv$Fluid Expression. My daily work calls on my core talents. I feel the field values the frequency of what I naturally am.$rsv$,'value',75), json_build_object('label',$rsv$Pure Transmission. There's no separation between what I am and what I do. My very existence, effortlessly, is the tool of manifestation.$rsv$,'value',100))::text) WHERE id = 'e05310cf-2292-422e-8130-26c9ea89f89a';
-- VECTOR · sonda 4
UPDATE public.sondas_config SET question_text_en = $rsv$When you look at the impact of your actions on the network (your environment, clients, humanity), what is your level of penetration?$rsv$, options_json_en = to_jsonb(json_build_array(json_build_object('label',$rsv$Entropy and Contraction. I operate only to survive or gain an edge. I feel my current existence adds nothing to the collective fabric.$rsv$,'value',0), json_build_object('label',$rsv$Short-Range Survival. I barely have the energy to hold up my inner circle; I have no bandwidth to affect anyone else.$rsv$,'value',25), json_build_object('label',$rsv$Transactional Impact. I deliver standard value. I give good service or a good product and I get paid. No harm done, but the transformation is surface-level.$rsv$,'value',50), json_build_object('label',$rsv$Elevating Nodes. My work actively improves the timeline of those around me. I feel the gratitude and the expansion of the field around me.$rsv$,'value',75), json_build_object('label',$rsv$Altering the Matrix. My vector transforms reality. My mere presence and work raise the frequency of collective consciousness toward Silicon.$rsv$,'value',100))::text) WHERE id = '35a531a0-2dab-4cc5-ab6c-6dfc93b9f497';
-- VECTOR · sonda 5
UPDATE public.sondas_config SET question_text_en = $rsv$When you face a "comfortable but empty" life, or a three-dimensional success with no soul, how does your system respond?$rsv$, options_json_en = to_jsonb(json_build_array(json_build_object('label',$rsv$Total Sedation. I accept the emptiness as long as I have distractions and material comfort. I gave up searching for a higher meaning.$rsv$,'value',0), json_build_object('label',$rsv$Painful Conformity. I know I'm meant for something bigger, but the terror of losing my apparent security keeps me paralyzed and suffering.$rsv$,'value',25), json_build_object('label',$rsv$Conditioned Balance. I try to balance material comfort with small doses of purpose, avoiding any abrupt move that would disturb the order.$rsv$,'value',50), json_build_object('label',$rsv$Breaking the Friction. I take calculated risks to leave comfort zones that no longer vibrate at my frequency, betting on my evolution.$rsv$,'value',75), json_build_object('label',$rsv$Intolerance to Emptiness. If an environment, project, or relationship has no soul, I abandon it at once no matter the material cost. I don't negotiate my voltage.$rsv$,'value',100))::text) WHERE id = 'c159d35a-2da5-480a-8737-ab3f008943c5';
-- VECTOR · sonda 6
UPDATE public.sondas_config SET question_text_en = $rsv$As you project your consciousness forward, how sharp is the image of the material and spiritual reality you're building?$rsv$, options_json_en = to_jsonb(json_build_array(json_build_object('label',$rsv$Temporal Blindness. I can't see the future. All I perceive is a black wall, uncertainty, anxiety, and the instinct to survive until tomorrow.$rsv$,'value',0), json_build_object('label',$rsv$Dense Fog. I have vague ideas or three-dimensional illusions, but no architectural plan or certainty of how to materialize them on the ground.$rsv$,'value',25), json_build_object('label',$rsv$Matrix Goals. I see clear goals, but ones imposed by the system (earn X money, buy something), not a vision of genuine spiritual expansion.$rsv$,'value',50), json_build_object('label',$rsv$Tactical Vision. I know exactly which ecosystem I'm building. I have the blueprint clear and I'm executing the steps to materialize it.$rsv$,'value',75), json_build_object('label',$rsv$Telepathic Certainty. I don't need to visualize by force, because the collapse already happened on the quantum plane. I simply walk the inevitable trajectory.$rsv$,'value',100))::text) WHERE id = '4de1899d-1a1f-415b-bbae-4b11c2853b73';
-- VECTOR · sonda 7
UPDATE public.sondas_config SET question_text_en = $rsv$When it's time to sit down and work on your main vision, how much internal resistance do you feel?$rsv$, options_json_en = to_jsonb(json_build_array(json_build_object('label',$rsv$Lethal Sabotage. I procrastinate endlessly. I freeze from impostor syndrome or fear of failure. I can't get started.$rsv$,'value',0), json_build_object('label',$rsv$Forced Start. Getting going is agonizing. Every step feels like pushing a giant boulder uphill.$rsv$,'value',25), json_build_object('label',$rsv$Mechanical Discipline. I use raw willpower to beat the laziness. Sometimes I win and move forward, sometimes I lose energy in the inner battle.$rsv$,'value',50), json_build_object('label',$rsv$Active Magnetism. There's minimal resistance at first, but the moment I take the first step, inertia pulls me into fluid action.$rsv$,'value',75), json_build_object('label',$rsv$Gravitational Attraction. Zero resistance. An invisible force pulls me toward the work. It's infinitely harder to stop the work than to start it.$rsv$,'value',100))::text) WHERE id = 'fe128953-476b-467a-adf3-80c7d77666c0';
-- VECTOR · sonda 8
UPDATE public.sondas_config SET question_text_en = $rsv$When you materialize your vision, how much do you dilute, alter, or "soften" your original code to make it more commercial, more digestible, or more accepted by the matrix?$rsv$, options_json_en = to_jsonb(json_build_array(json_build_object('label',$rsv$Prostituting the Code. I do exactly what the market asks. I've abandoned my original vision to fit in and sell, betraying my aesthetic and my truth.$rsv$,'value',0), json_build_object('label',$rsv$Dilution from Fear. I have my vision, but I hide it. I soften the message and lower the fidelity of my work, terrified that "no one will get it" or that I'll be rejected.$rsv$,'value',25), json_build_object('label',$rsv$Commercial Adaptation. I keep the essence, but I make concessions in design or depth to secure viability and not unsettle the average client.$rsv$,'value',50), json_build_object('label',$rsv$Protected Fidelity. My work comes out nearly intact. I make minimal adjustments only if they improve usability or the interface, but I never negotiate the core frequency.$rsv$,'value',75), json_build_object('label',$rsv$Uncompromising Transmission. Absolute high fidelity. My code comes down raw and perfect. I don't lower the resolution of my architecture for the world to understand it; I demand that the world raise its perception to reach my work.$rsv$,'value',100))::text) WHERE id = 'ac9abf02-ba77-42b2-b14b-59f91924b808';

